rss.channel:
  Clementine
  https://www.clementine-player.org/
  Clementine Player
  en
{#
  The MacUpdate entities Clementine's tools/mac-update publishes. The notes
  are plain text, which Sparkle shows as written, in a native text view
  rather than a web view; the template's autoescaping makes them XML text.
#}
{% for update in updates %}


    Clementine {{ update.version }}
    {{ update.published|rfc2822 }}
    {# The app's CFBundleVersion, which Sparkle compares. #}
    {{ update.build }}
    {{ update.version }}
    {{ update.min_macos }}
    {{ update.notes_text }}


{% endfor %}
